package com.example.bandlink.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="conversations", uniqueConstraints=@UniqueConstraint(name="uk_conversation_pair",columnNames={"user_a_id","user_b_id"}))
public class Conversation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_a_id") private User userA; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_b_id") private User userB; @Column(nullable=false) private LocalDateTime createdAt; private LocalDateTime lastMessageAt; protected Conversation(){} public Conversation(User a,User b,LocalDateTime now){if(a.getId()!=null&&b.getId()!=null&&a.getId()>b.getId()){var t=a;a=b;b=t;}userA=a;userB=b;createdAt=now;lastMessageAt=now;} public Long getId(){return id;} public User getUserA(){return userA;} public User getUserB(){return userB;} public LocalDateTime getLastMessageAt(){return lastMessageAt;} public void touch(LocalDateTime now){lastMessageAt=now;} public boolean includes(Long userId){return userA.getId().equals(userId)||userB.getId().equals(userId);} }
